SC.speakSequence=(parts,sourceId,once=false)=>{SC.stopSpeech();speechQueue=parts.filter(p=>p.text?.trim()&&(once||(p.lang||'ko')==='ko')).map(p=>({text:p.text,lang:p.lang||'ko',sentence:p.sentence===true}));for(const part of speechQueue){const key=voiceKey(part);if(generatedVoices.get(key)?.failed)generatedVoices.delete(key);}speechRepeats=!once;speechSource=sourceId||speechKey(speechQueue);queueIndex=0;if(speechQueue.length)playSpeech(audioEpoch);};
