  dog.addEventListener('pointermove',event=>{if(!fine.matches||document.hidden)return;const rect=dog.getBoundingClientRect(),x=Math.max(-1,Math.min(1,(event.clientX-(rect.left+rect.width/2))/(rect.width/2)));dog.style.transform=`rotate(${x*11}deg)`;});
