SC.loadDemoSong=()=>SC.song;
function nextLineTime(index){if(SC.songLineEnd)return SC.songLineEnd(index);const time=SC.song.lines[index]?.t||0;return SC.song.lines.slice(index+1).find(line=>line.t>time)?.t||SC.song.duration;}
