SC.setLoop=(mode,value)=>{const index=mode==='line'?value:Array.isArray(value)?value[0]:null,endIndex=mode==='section'?value[1]:index;if((mode==='line'||mode==='section')&&(!Number.isInteger(index)||!Number.isFinite(SC.song.lines[index]?.t)||!Number.isFinite(SC.song.lines[endIndex]?.t)||nextLineTime(endIndex)<=SC.song.lines[index].t)){SC.toast('先校对所选歌词的起止时间，再开启循环。');return;}SC.player.clip=null;SC.player.loopMode=mode;SC.player.audio.loop=mode==='all';if(mode==='line'){SC.player.lineIndex=value;SC.seek(SC.song.lines[value].t);}if(mode==='section'){SC.player.section=value;SC.seek(SC.song.lines[value[0]].t);}updatePlayer();};
SC.ensureSongBooks=(includeSentences=false,song=SC.song)=>{const projectId='song:'+song.id;let project=SC.data.projects.find(p=>p.id===projectId);if(!project){project={id:projectId,name:song.title,expanded:true,modules:[],groupId:null};SC.data.projects.push(project);}let words=SC.data.books.find(b=>b.projectId===projectId&&b.kind==='word'),grammar=SC.data.books.find(b=>b.projectId===projectId&&b.kind==='grammar');if(!words){words={id:id(),name:'单词卡',kind:'word',projectId:projectId};SC.data.books.push(words);}if(!grammar){grammar={id:id(),name:'语法卡',kind:'grammar',projectId:projectId};SC.data.books.push(grammar);}let sentences=SC.data.books.find(book=>book.projectId===projectId&&book.kind==='sentence');if(includeSentences&&!sentences){sentences={id:id(),name:'句子卡',kind:'sentence',projectId};SC.data.books.push(sentences);}return {project,words,grammar,sentences};};
function formatTime(time){return `${Math.floor(time/60)}:${String(Math.floor(time%60)).padStart(2,'0')}`;}
function scheduleBoundary(){const p=SC.player,audio=p.audio;clearTimeout(p.boundaryTimer);if(p.stopped||(audio.paused&&!audio.ended)||!p.available)return;let start,end;if(p.clip){({start,end}=p.clip);}else if(p.loopMode==='line'){start=SC.song.lines[p.lineIndex]?.t;end=nextLineTime(p.lineIndex);}else if(p.loopMode==='section'){start=SC.song.lines[p.section[0]]?.t;end=nextLineTime(p.section[1]);}if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)return;if(audio.currentTime>=end-.015){if(p.clip){const index=p.clip.index;p.clip=null;audio.pause();audio.currentTime=Math.max(start,end-.001);p.activeLine=index;}else{const ended=audio.ended;audio.currentTime=start;if(ended)SC.playSong();}updatePlayer();return;}p.boundaryTimer=setTimeout(scheduleBoundary,Math.max(20,(end-audio.currentTime)*1000/audio.playbackRate));}
function updatePlayer(){const p=SC.player;if(!p)return;const audio=p.audio,time=audio.currentTime;const elapsed=SC.$('#elapsed'),seek=SC.$('#songSeek'),play=SC.$('#playSong'),duration=SC.$('#duration'),loop=SC.$('#loopSong'),volume=SC.$('#volumeButton');if(elapsed)elapsed.textContent=formatTime(time);if(seek){seek.max=String(SC.song.duration);seek.value=String(time);seek.disabled=!p.available;}if(duration)duration.textContent=formatTime(SC.song.duration);if(play){play.innerHTML=SC.icon(audio.paused?'play':'pause');play.setAttribute('aria-label',audio.paused?'播放':'暂停');play.disabled=!p.available;}if(loop){loop.classList.toggle('active',!!p.loopMode);loop.title=({line:'单句循环',section:'选段循环',all:'整曲循环'})[p.loopMode]||'循环模式';}if(volume){volume.classList.toggle('active',audio.muted);volume.setAttribute('aria-label',audio.muted?'取消静音':'静音歌曲');}let index=-1;SC.song.lines.forEach((line,i)=>{if(Number.isFinite(line.t)&&time>=line.t)index=i;});p.activeLine=index;if(SC.route==='songs'&&SC.songTimeUpdate)SC.songTimeUpdate(time);scheduleBoundary();}
SC.updatePlayer=updatePlayer;
SC.loadSongFile=async file=>{if(!file)return;const ext=/\.(mp3|wav|m4a|ogg|flac|aac|webm)$/i.test(file.name);if(!file.type.startsWith('audio/')&&!ext){SC.toast('请选择音频文件。');return false;}const epoch=++SC.player.loadEpoch,url=URL.createObjectURL(file),probe=new Audio();probe.preload='metadata';const duration=await new Promise(resolve=>{const timer=setTimeout(()=>resolve(0),12000);probe.onloadedmetadata=()=>{clearTimeout(timer);resolve(probe.duration);};probe.onerror=()=>{clearTimeout(timer);resolve(0);};probe.src=url;});probe.removeAttribute('src');probe.load();if(epoch!==SC.player.loadEpoch){URL.revokeObjectURL(url);return false;}if(!Number.isFinite(duration)||duration<=0){URL.revokeObjectURL(url);SC.toast('这个音频无法读取，原有音源保持不变。');return false;}SC.stopSpeech();const p=SC.player,old=p.objectUrl;p.audio.pause();p.clip=null;p.objectUrl=url;p.available=true;p.sourceName=file.name;p.sourceDuration=duration;p.ready=new Promise(resolve=>p.audio.addEventListener('loadedmetadata',resolve,{once:true}));p.audio.src=url;await p.ready;if(old)URL.revokeObjectURL(old);if(SC.route==='songs'){SC.songRender(SC.root);sidebar();}if(Math.abs(duration-SC.song.duration)>3)SC.toast('音频时长与录音室版不符，请核对版本及歌词同步。');else SC.toast('本地音源已接入，请试听核对歌词同步。');return true;};
SC.wireSongControls=()=>{if(!SC.$('#playSong'))return;['previousLine','nextLine','loopSong','volumeButton'].forEach((name,i)=>{const el=SC.$('#'+name);if(el)el.innerHTML=SC.icon(['left','right','loop','sound'][i]);});SC.$('#playSong').onclick=()=>{SC.player.clip=null;SC.player.audio.paused?SC.playSong():SC.player.audio.pause();};SC.$('#previousLine').onclick=()=>{const t=SC.song.lines[Math.max(0,SC.player.activeLine-1)]?.t;if(Number.isFinite(t))SC.seek(t);};SC.$('#nextLine').onclick=()=>{const t=SC.song.lines[Math.min(SC.song.lines.length-1,SC.player.activeLine+1)]?.t;if(Number.isFinite(t))SC.seek(t);};SC.$('#songSeek').oninput=e=>SC.seek(e.target.value);SC.$('#loopSong').onclick=e=>openMenu(e.currentTarget.getBoundingClientRect().left,e.currentTarget.getBoundingClientRect().top-140,[{label:'单句循环',icon:'loop',fn:()=>SC.setLoop('line',Math.max(0,SC.player.activeLine))},{label:'选段循环',icon:'loop',fn:()=>SC.setLoop('section',[Math.max(0,SC.player.activeLine),Math.min(SC.song.lines.length-1,Math.max(0,SC.player.activeLine)+1)])},{label:'整曲循环',icon:'loop',fn:()=>SC.setLoop('all')},{label:'关闭循环',icon:'close',fn:()=>SC.setLoop(null)}]);SC.$('#volumeButton').onclick=()=>{SC.player.audio.muted=!SC.player.audio.muted;updatePlayer();};const input=SC.$('#songAudioInput');if(input){input.onchange=e=>{SC.loadSongFile(e.target.files[0]);e.target.value='';};SC.$('.song-audio-file')?.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.repeat&&!e.isComposing){e.preventDefault();input.click();}});}updatePlayer();};
function playerInit(){SC.player={audio:SC.$('#songAudio'),loopMode:null,activeLine:-1,lineIndex:0,section:[0,1],available:false,sourceName:'',ready:Promise.resolve(),clip:null,loadEpoch:0};['timeupdate','play','pause','ended','seeked','ratechange','playing'].forEach(event=>SC.player.audio.addEventListener(event,updatePlayer));SC.player.audio.addEventListener('error',()=>{if(SC.player.available){SC.player.available=false;SC.toast('本地音频播放失败，请更换音源。');updatePlayer();}});}
const routeNames={home:'主页',songs:'KPOP',words:'单词卡',grammar:'语法卡',sentences:'句子卡',expressions:'常用表达',forms:'词形变化',sentence:'拼句练习',combined:'综合练习'};
const isBookRoute=route=>['words','grammar','sentences'].includes(route);
const recent=list=>[...list].sort((a,b)=>(b.lastUsed||0)-(a.lastUsed||0));
paths.reviewRepeat='M6 5h10v14H6ZM9 9h4M9 13h4M3 10V6l3-3M3 6h3M19 14v4l-3 3M19 18h-3';
const liveContainer=row=>!row.deleted&&!SC.data.deletedContainers?.[row.id];
const sidebarGroups=()=>SC.data.groups.filter(liveContainer);
const notebookScope=project=>sidebarGroups().some(group=>group.id===project.groupId)?project.groupId:'';
const notebooksInScope=scope=>SC.data.projects.filter(project=>liveContainer(project)&&notebookScope(project)===(scope||''));
const orderedBooks=list=>[...list].filter(book=>!book.special&&liveContainer(book)).sort((a,b)=>['word','grammar','sentence'].indexOf(a.kind)-['word','grammar','sentence'].indexOf(b.kind));
SC.orderedBooks=orderedBooks;
const orderedModules=project=>['expressions','forms','sentence'].filter(module=>project.modules.includes(module));
const directBooks=scope=>orderedBooks(SC.data.books.filter(book=>!book.projectId&&(book.groupId||'')===(scope||'')));
function stableSidebarSlots(list,previous=[]){const valid=new Set(list.map(row=>row.id)),slots=[...new Set(previous)].filter(value=>valid.has(value)).slice(0,3);for(const row of recent(list))if(slots.length<3&&!slots.includes(row.id))slots.push(row.id);return slots;}
function syncSidebarVisible(){
  const previous=SC.data.sidebarVisible||{},groups=sidebarGroups(),notebooks={};
  for(const scope of ['',...groups.map(group=>group.id)])notebooks[scope]=stableSidebarSlots(notebooksInScope(scope),previous.notebooks?.[scope]);
  const next={groups:stableSidebarSlots(groups,previous.groups),notebooks};
  if(JSON.stringify(previous)===JSON.stringify(next))return false;SC.data.sidebarVisible=next;return true;
}
function visibleContainers(list,kind,scope=''){const slots=kind==='group'?SC.data.sidebarVisible.groups:SC.data.sidebarVisible.notebooks[scope];return slots.map(value=>list.find(row=>row.id===value)).filter(Boolean);}
function allContainers(list,kind,scope=''){const visible=visibleContainers(list,kind,scope),ids=new Set(visible.map(row=>row.id));return [...visible,...recent(list).filter(row=>!ids.has(row.id))];}
function touchSidebarContainer(entity,kind){
  if(!SC.data.sidebarVisible)syncSidebarVisible();const scope=kind==='group'?'':notebookScope(entity),previous=kind==='group'?SC.data.sidebarVisible.groups:SC.data.sidebarVisible.notebooks[scope]||[];
  const wasVisible=previous.includes(entity.id);syncSidebarVisible();const list=kind==='group'?sidebarGroups():notebooksInScope(scope);
  if(!list.some(row=>row.id===entity.id))return;
  const slots=kind==='group'?SC.data.sidebarVisible.groups:SC.data.sidebarVisible.notebooks[scope];
  if(!wasVisible){const index=slots.indexOf(entity.id);if(index!==-1)slots.splice(index,1);if(slots.length===3){let oldest=0;for(let i=1;i<slots.length;i++)if((list.find(row=>row.id===slots[i])?.lastUsed||0)<=(list.find(row=>row.id===slots[oldest])?.lastUsed||0))oldest=i;slots.splice(oldest,1);}slots.unshift(entity.id);}
  entity.lastUsed=Date.now();
}
function moreButton(kind,scope){return `<button type="button" class="nav-item sidebar-more" data-more-kind="${kind}" data-more-scope="${SC.esc(scope||'')}" aria-label="更多${({group:'项目',project:'笔记本',book:'卡片',children:'内容'})[kind]}" title="更多">${SC.icon('more')}<span>更多</span></button>`;}
function limited(list,render,kind,scope=''){return visibleContainers(list,kind,scope).map(render).join('')+(list.length>3?moreButton(kind,scope):'');}
function groupChildren(groupId){return [...allContainers(notebooksInScope(groupId),'project',groupId),...directBooks(groupId)];}
function browseCollection(kind,scope=''){if(syncSidebarVisible())SC.persist();const list=kind==='group'?allContainers(sidebarGroups(),'group'):kind==='children'?groupChildren(scope):kind==='project'?allContainers(notebooksInScope(scope),'project',scope):orderedBooks(SC.data.books.filter(book=>SC.bookInScope(book,scope||null,null)));const name=({group:'项目',project:'笔记本',book:'卡片',children:'内容'})[kind];SC.info(`选择${name}`,`<div class="collection-browser"><input class="collection-search" type="search" placeholder="搜索${name}" aria-label="搜索${name}"><div class="collection-results">${list.map(entity=>`<button type="button" class="collection-entry" data-collection="${SC.esc(entity.id)}">${SC.icon(kind==='group'?'folder':entity.kind?SC.cardIcon(entity.kind):'notebook')}<span>${SC.esc(entity.name)}</span></button>`).join('')}</div></div>`);const search=SC.$('.collection-search');search.oninput=()=>SC.$('.collection-results').querySelectorAll('[data-collection]').forEach(button=>{button.hidden=!button.textContent.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase());});SC.$('.collection-results').querySelectorAll('[data-collection]').forEach(button=>button.onclick=()=>{const entity=list.find(value=>value.id===button.dataset.collection);if(!entity)return;SC.$('#dialog').close();if(kind==='group'){touchSidebarContainer(entity,'group');entity.expanded=true;SC.persist();sidebar();if(SC.data.sidebarCollapsed)collapsedGroup(entity);}else SC.go(entity.kind?cardRoute(entity.kind):'home',entity.id);});SC.wireCollectionManagement?.(kind,list);search.focus();}
function navButton(route,label,icon,entityId='',extra=''){const active=SC.route===route&&(entityId?entityId===(isBookRoute(route)?SC.bookId:SC.projectId):true);return `<button class="nav-item ${extra} ${active?'active':''}" data-route="${route}" data-id="${SC.esc(entityId)}" title="${SC.esc(label)}" aria-label="${SC.esc(label)}">${SC.icon(icon)}<span>${SC.esc(label)}</span></button>`;}
function bookNav(book){return `<div class="book-nav" draggable="${!book.special}" data-book="${SC.esc(book.id)}">${navButton(book.special?'words':cardRoute(book.kind),book.name,book.special?'reviewRepeat':SC.cardIcon(book.kind),book.id,book.special?'':'child')}</div>`;}
function notebookNav(project){const books=orderedBooks(SC.data.books.filter(book=>book.projectId===project.id));return `<div class="project-nav" draggable="true" data-project="${SC.esc(project.id)}"><button class="nav-item project-title" data-project-home="${SC.esc(project.id)}" title="${SC.esc(project.name)}" aria-label="${SC.esc(project.name)}">${SC.icon('notebook')}<span>${SC.esc(project.name)}</span><span class="expand-project" role="button" tabindex="0" aria-label="${project.expanded?'收起':'展开'} ${SC.esc(project.name)}">${SC.icon(project.expanded?'down':'right')}</span></button>${project.expanded&&!SC.data.sidebarCollapsed?books.map(bookNav).join('')+orderedModules(project).map(module=>navButton(module,routeNames[module],'wave',project.id,'child')).join(''):''}</div>`;}
function collapsedNotebook(project){const box=SC.$(`[data-project-home="${project.id}"]`)?.getBoundingClientRect()||{right:84,top:90},books=orderedBooks(SC.data.books.filter(book=>book.projectId===project.id));openMenu(box.right+6,box.top,[{label:project.name,icon:'notebook',fn:()=>SC.go('home',project.id)},{separator:true},...books.map(book=>({label:book.name,icon:SC.cardIcon(book.kind),fn:()=>SC.go(cardRoute(book.kind),book.id)})),...orderedModules(project).map(module=>({label:routeNames[module],icon:'wave',fn:()=>SC.go(module,project.id)}))]);}
function collapsedGroup(group){const box=SC.$(`[data-group-toggle="${group.id}"]`)?.getBoundingClientRect()||{right:84,top:90},notebooks=notebooksInScope(group.id),children=[...visibleContainers(notebooks,'project',group.id),...directBooks(group.id)];openMenu(box.right+6,box.top,[{label:group.name,icon:'folder',fn:()=>SC.go('home',group.id)},{separator:true},...children.map(entity=>({label:entity.name,icon:entity.kind?SC.cardIcon(entity.kind):'notebook',fn:()=>entity.kind?SC.go(cardRoute(entity.kind),entity.id):collapsedNotebook(entity)})),...(notebooks.length>3?[{label:'更多内容',icon:'more',fn:()=>browseCollection('children',group.id)}]:[])]);}
function sidebar(){
  if(syncSidebarVisible())SC.persist();
  SC.hideHouseTooltip?.();SC.$('#hoverPreview').hidden=true;
  document.body.classList.toggle('sidebar-collapsed',!!SC.data.sidebarCollapsed);SC.$('.brand').setAttribute('aria-expanded',String(!SC.data.sidebarCollapsed));SC.$('.brand').setAttribute('aria-label',SC.data.sidebarCollapsed?'展开侧栏':'收起侧栏');
  const groups=limited(sidebarGroups(),group=>`<div class="group-nav" data-group="${SC.esc(group.id)}"><button class="nav-item group-title" data-group-toggle="${SC.esc(group.id)}" title="${SC.esc(group.name)}" aria-label="${SC.esc(group.name)}">${SC.icon('folder')}<span>${SC.esc(group.name)}</span>${SC.icon(group.expanded?'down':'right')}</button>${group.expanded&&!SC.data.sidebarCollapsed?`<div class="group-notebooks">${limited(notebooksInScope(group.id),notebookNav,'children',group.id)}${directBooks(group.id).map(bookNav).join('')}</div>`:''}</div>`,'group','');
  const other=limited(notebooksInScope(''),notebookNav,'project','');
  SC.$('#sidebarNav').innerHTML=`${navButton('home','主页','home')}${bookNav(SC.data.books.find(book=>book.id===EXTRA_BOOK)||extraBook())}${navButton('combined','综合练习','wave')}${navButton('songs','KPOP','music')}<div class="nav-heading"><span>项目</span></div>${groups}<div class="nav-heading"><span>其他</span></div><div id="otherBooks">${other}${directBooks('').map(bookNav).join('')}</div>`;
  SC.$('#sidebarNav').querySelectorAll('[data-more-kind]').forEach(button=>button.onclick=()=>browseCollection(button.dataset.moreKind,button.dataset.moreScope));
  SC.$('#sidebarNav').querySelectorAll('[data-route]').forEach(button=>button.onclick=()=>SC.go(button.dataset.route,button.dataset.id));
  SC.$('#sidebarNav [data-route=home]').oncontextmenu=event=>{event.preventDefault();openMenu(event.clientX,event.clientY,[{label:'新对话',icon:'plus',fn:()=>{clearConversation();SC.go('home');}}]);};

  SC.$('#sidebarNav').querySelectorAll('[data-group]').forEach(element=>{const group=SC.data.groups.find(group=>group.id===element.dataset.group);element.querySelector('[data-group-toggle]').onclick=()=>{if(SC.data.sidebarCollapsed){collapsedGroup(group);return;}group.expanded=!group.expanded;SC.persist();sidebar();};element.oncontextmenu=event=>{if(event.target.closest('[data-project],[data-book]'))return;event.preventDefault();groupMenu(group.id,event.clientX,event.clientY);};element.ondragover=event=>{if(event.dataTransfer.types.includes('text/scrawl-notebook')||event.dataTransfer.types.includes('text/scrawl-book')){event.preventDefault();element.classList.add('drag-over');}};element.ondragleave=()=>element.classList.remove('drag-over');element.ondrop=event=>{const notebookId=event.dataTransfer.getData('text/scrawl-notebook'),bookId=event.dataTransfer.getData('text/scrawl-book');if(!notebookId&&!bookId)return;event.preventDefault();event.stopPropagation();element.classList.remove('drag-over');if(notebookId)moveNotebook(notebookId,group.id);else moveBook(bookId,null,group.id);};});
  SC.$('#sidebarNav').querySelectorAll('[data-project-home]').forEach(button=>{button.onclick=event=>{if(SC.data.sidebarCollapsed){const project=SC.data.projects.find(value=>value.id===button.dataset.projectHome);collapsedNotebook(project);return;}if(event.target.closest('.expand-project')){const project=SC.data.projects.find(project=>project.id===button.dataset.projectHome);project.expanded=!project.expanded;SC.persist();sidebar();}else SC.go('home',button.dataset.projectHome);};button.querySelector('.expand-project').onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();event.stopPropagation();button.querySelector('.expand-project').click();}};});
  SC.$('#sidebarNav').querySelectorAll('[data-project]').forEach(element=>{element.ondragstart=event=>{if(event.target.closest('[data-book]'))return;SC.stopSpeech();SC.sidebarDragging=true;event.dataTransfer.setData('text/scrawl-notebook',element.dataset.project);SC.$('#hoverPreview').hidden=true;};element.oncontextmenu=event=>{event.preventDefault();event.stopPropagation();projectMenu(element.dataset.project,event.clientX,event.clientY);};element.ondragover=event=>{if(event.dataTransfer.types.includes('text/scrawl-book')){event.preventDefault();element.classList.add('drag-over');}};element.ondragleave=()=>element.classList.remove('drag-over');element.ondrop=event=>{const bookId=event.dataTransfer.getData('text/scrawl-book');if(!bookId)return;event.preventDefault();event.stopPropagation();element.classList.remove('drag-over');moveBook(bookId,element.dataset.project);};});
  SC.$('#sidebarNav').querySelectorAll('[data-book]').forEach(element=>{element.ondragstart=event=>{if(SC.data.books.find(book=>book.id===element.dataset.book)?.special){event.preventDefault();return;}SC.stopSpeech();SC.sidebarDragging=true;event.dataTransfer.setData('text/scrawl-book',element.dataset.book);SC.$('#hoverPreview').hidden=true;};element.oncontextmenu=event=>{event.preventDefault();event.stopPropagation();bookMenu(element.dataset.book,event.clientX,event.clientY);};});
  SC.$('#otherBooks').ondragover=event=>event.preventDefault();SC.$('#otherBooks').ondrop=event=>{event.preventDefault();const notebookId=event.dataTransfer.getData('text/scrawl-notebook');if(notebookId)moveNotebook(notebookId,null);else moveBook(event.dataTransfer.getData('text/scrawl-book'),null);};
  SC.wireSidebarManagement?.();
}
SC.refreshSidebar=sidebar;
function sidebarPointerDrag(){
  let drag=null,highlight=null,suppressClick=false;
  const clear=()=>{highlight?.classList.remove('drag-over');highlight=null;drag=null;SC.sidebarDragging=false;};
  document.addEventListener('pointerdown',event=>{
    if(event.button!==0||event.pointerType==='touch'||!event.target.closest('#sidebarNav')||event.target.closest('.expand-project'))return;
    const source=event.target.closest('[data-book],[data-project]');if(!source)return;
    if(source.dataset.book&&SC.data.books.find(book=>book.id===source.dataset.book)?.special)return;
    drag={bookId:source.dataset.book,notebookId:source.dataset.project,x:event.clientX,y:event.clientY,active:false};
  });
  document.addEventListener('dragstart',event=>{const source=event.target.closest('[data-book],[data-project]');if(drag&&source&&(drag.bookId?source.dataset.book!==drag.bookId:source.dataset.project!==drag.notebookId)){event.preventDefault();event.stopPropagation();return;}clear();},true);document.addEventListener('dragend',clear);
  document.addEventListener('pointercancel',clear);window.addEventListener('blur',clear);document.addEventListener('visibilitychange',()=>{if(document.hidden)clear();});
  document.addEventListener('pointermove',event=>{
    if(!drag)return;if(!drag.active&&Math.hypot(event.clientX-drag.x,event.clientY-drag.y)<7)return;
    if(!drag.active){drag.active=true;SC.sidebarDragging=true;SC.stopSpeech();SC.$('#hoverPreview').hidden=true;}
    event.preventDefault();highlight?.classList.remove('drag-over');
    const target=document.elementFromPoint(event.clientX,event.clientY),parent=target?.closest(drag.bookId?'[data-project],[data-group]':'[data-group]');
    highlight=parent?.querySelector(parent.dataset.project?'.project-title':'.group-title');highlight?.classList.add('drag-over');
  });
  document.addEventListener('pointerup',event=>{
    if(!drag?.active){clear();return;}const source=drag,target=document.elementFromPoint(event.clientX,event.clientY);clear();
    suppressClick=true;setTimeout(()=>suppressClick=false,0);event.preventDefault();
    if(source.bookId){const notebook=target?.closest('[data-project]'),group=target?.closest('[data-group]');if(notebook)moveBook(source.bookId,notebook.dataset.project);else if(group)moveBook(source.bookId,null,group.dataset.group);else if(target?.closest('#otherBooks'))moveBook(source.bookId,null);}
    else{const group=target?.closest('[data-group]');if(group)moveNotebook(source.notebookId,group.dataset.group);else if(target?.closest('#otherBooks'))moveNotebook(source.notebookId,null);}
  },true);
  document.addEventListener('click',event=>{if(suppressClick&&event.target.closest('#sidebarNav')){event.preventDefault();event.stopImmediatePropagation();}},true);
}
let menuTrigger=null;
function closeMenu(restore=true){const menu=SC.$('#contextMenu');menu.hidden=true;if(menu.parentElement!==document.body)document.body.append(menu);menuTrigger?.setAttribute('aria-expanded','false');if(restore&&menuTrigger?.isConnected)menuTrigger.focus();menuTrigger=null;}
function openMenu(x,y,items,trigger=null){
  closeMenu(false);const menu=SC.$('#contextMenu'),dialog=SC.$('#dialog');(dialog.open?dialog:document.body).append(menu);menuTrigger=trigger;trigger?.setAttribute('aria-expanded','true');menu.classList.toggle('notebook-menu',!!trigger);
  menu.innerHTML=items.map((entry,i)=>entry.separator?'<div class="menu-separator"></div>':`<button type="button" role="${typeof entry.selected==='boolean'?'menuitemradio':'menuitem'}" ${typeof entry.selected==='boolean'?`aria-checked="${entry.selected}"`:''} class="${entry.selected?'selected':''}" data-menu="${i}">${SC.icon(entry.icon||'book')}<span>${SC.esc(entry.label)}</span>${entry.selected?SC.icon('check'):''}</button>`).join('');
  menu.hidden=false;menu.style.left=`${Math.max(8,Math.min(innerWidth-menu.offsetWidth-8,x))}px`;menu.style.top=`${Math.max(8,Math.min(innerHeight-menu.offsetHeight-10,y))}px`;
  menu.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>{closeMenu();items[Number(b.dataset.menu)].fn();});menu.querySelector('[aria-checked=true],button')?.focus();
}
SC.closeMenu=closeMenu;
function houseSelects(){
  document.querySelectorAll('select:not([data-house-select])').forEach(select=>{
    select.dataset.houseSelect='true';select.hidden=true;select.tabIndex=-1;
    const button=document.createElement('button');button.type='button';button.className='house-select plain-button';button.setAttribute('aria-haspopup','menu');button.setAttribute('aria-controls','contextMenu');button.setAttribute('aria-expanded','false');select.after(button);
    const sync=()=>{button.disabled=select.disabled||![...select.options].some(option=>!option.disabled&&!option.hidden);button.innerHTML=`<span>${SC.esc(select.selectedOptions[0]?.textContent||'选择')}</span>${SC.icon('down')}`;button.setAttribute('aria-label',select.getAttribute('aria-label')||select.closest('label')?.firstChild?.textContent?.trim()||select.name||select.id||'选择');};
    const show=()=>{if(button.disabled)return;if(menuTrigger===button&&!SC.$('#contextMenu').hidden){closeMenu();return;}const box=button.getBoundingClientRect();openMenu(box.left,box.bottom+5,[...select.options].filter(option=>!option.disabled&&!option.hidden).map(option=>({label:option.textContent,selected:option.value===select.value,fn:()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));sync();}})),button);};
    button.onclick=show;button.onkeydown=event=>{if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();show();}};
    select.addEventListener('change',sync);new MutationObserver(sync).observe(select,{subtree:true,childList:true,attributes:true,attributeFilter:['disabled','selected']});sync();
  });
}
SC.houseSelects=houseSelects;
SC.openBookMenu=(trigger,kind,selected,onSelect)=>{
  if(menuTrigger===trigger&&!SC.$('#contextMenu').hidden){closeMenu();return;}
  const books=SC.data.books.filter(b=>b.kind===kind&&SC.bookInScope(b)),box=trigger.getBoundingClientRect();
  const items=books.map(book=>({label:book.name,selected:book.id===selected,fn:()=>onSelect(book.id)}));
  if(books.length)items.push({separator:true});items.push({label:'新建'+SC.cardLabel(kind),icon:SC.cardIcon(kind),fn:()=>createBook(kind,SC.projectId,SC.groupId)});
  openMenu(box.left,box.bottom+6,items,trigger);
};
function createGroup(){SC.editFields('新建项目',[{key:'name',label:'项目名称',value:'',required:true}],values=>{syncSidebarVisible();const group={id:id(),name:values.name.trim(),expanded:true};SC.data.groups.push(group);touchSidebarContainer(group,'group');SC.persist();SC.render();});}
function createProject(groupId=null){SC.editFields('新建笔记本',[{key:'name',label:'笔记本名称',value:'',required:true}],values=>{const project={id:id(),name:values.name.trim(),expanded:true,modules:[],groupId,lastUsed:Date.now()};SC.data.projects.push(project);const group=SC.data.groups.find(group=>group.id===groupId);if(group)group.expanded=true;SC.persist();SC.go('home',project.id);});}
function moveNotebook(notebookId,groupId){const notebook=SC.data.projects.find(project=>project.id===notebookId);if(!notebook||(groupId&&!SC.data.groups.some(group=>group.id===groupId)))return;const old=notebook.groupId;notebook.groupId=groupId;const group=SC.data.groups.find(group=>group.id===groupId);if(group)group.expanded=true;SC.persist();SC.render();SC.toast('笔记本已移动。',()=>notebook.groupId=old);}
function groupMenu(groupId,x,y){if(SC.ui.sidebarSelection)return;const group=SC.data.groups.find(group=>group.id===groupId);if(!group)return;openMenu(x,y,[...SC.workbookUndoEntries(groupId),{label:'新建笔记本',icon:'notebook',fn:()=>createProject(groupId)},...['word','grammar','sentence'].map(kind=>({label:'新建'+SC.cardLabel(kind),icon:SC.cardIcon(kind),fn:()=>createBook(kind,null,groupId)})),{label:'重命名',icon:'pencil',fn:()=>SC.editFields('重命名',[{key:'name',label:'项目名称',value:group.name,required:true}],values=>{group.name=values.name.trim();SC.persist();SC.render();})},{separator:true},{label:'删除…',icon:'deleteAll',fn:()=>SC.beginContainerDelete('group',groupId)}]);}
function createBook(kind,projectId,groupId=null){SC.editFields('新建'+SC.cardLabel(kind),[{key:'name',label:'卡片名称',value:SC.cardLabel(kind),required:true}],values=>{const book={id:id(),name:values.name.trim(),kind,projectId:projectId||null,groupId:projectId?null:groupId,lastUsed:Date.now()};SC.data.books.push(book);const project=SC.data.projects.find(project=>project.id===projectId),group=SC.data.groups.find(group=>group.id===groupId);if(project)project.expanded=true;if(group)group.expanded=true;SC.persist();SC.go(cardRoute(kind),book.id);});}
function moveBook(bookId,projectId,groupId=null){const book=SC.data.books.find(book=>book.id===bookId);if(!book||book.special||(projectId&&!SC.data.projects.some(project=>project.id===projectId))||(groupId&&!SC.data.groups.some(group=>group.id===groupId)))return;const old={projectId:book.projectId,groupId:book.groupId||null};book.projectId=projectId||null;book.groupId=projectId?null:groupId;const project=SC.data.projects.find(project=>project.id===projectId),group=SC.data.groups.find(group=>group.id===groupId);if(project)project.expanded=true;if(group)group.expanded=true;const sync=()=>{if(isBookRoute(SC.route)&&SC.bookId===book.id){SC.projectId=book.projectId;SC.groupId=book.groupId;}};sync();SC.persist();SC.render();SC.toast('卡片已移动。',()=>{Object.assign(book,old);sync();});}
function bookMenu(bookId,x,y){if(SC.ui.sidebarSelection)return;const book=SC.data.books.find(book=>book.id===bookId);if(!book)return;if(book.special){openMenu(x,y,[...SC.workbookUndoEntries(bookId),{label:'打开',icon:'reviewRepeat',fn:()=>SC.go('words',book.id)}]);return;}openMenu(x,y,[...SC.workbookUndoEntries(bookId),...(SC.canUndoDittoWordRestore?.(bookId)?[{label:'撤销 Word 恢复',icon:'undo',fn:()=>SC.undoDittoWordRestore()}]:[]),{label:'重命名',icon:'pencil',fn:()=>SC.editFields('重命名',[{key:'name',label:'卡片名称',value:book.name,required:true}],values=>{book.name=values.name.trim();SC.persist();SC.render();})},...SC.data.groups.filter(group=>group.id!==book.groupId).map(group=>({label:'移到 '+group.name,icon:'folder',fn:()=>moveBook(bookId,null,group.id)})),...SC.data.projects.filter(project=>project.id!==book.projectId).map(project=>({label:'移到 '+project.name,icon:'notebook',fn:()=>moveBook(bookId,project.id)})),...(book.projectId||book.groupId?[{label:'移到其他',icon:'notebook',fn:()=>moveBook(bookId,null)}]:[]),{separator:true},{label:'删除…',icon:'deleteAll',fn:()=>SC.beginContainerDelete('book',bookId)}]);}
function projectMenu(projectId,x,y){if(SC.ui.sidebarSelection)return;const project=SC.data.projects.find(project=>project.id===projectId);if(!project)return;openMenu(x,y,[...SC.workbookUndoEntries(projectId),...(SC.canUndoDittoWordRestore?.(projectId)?[{label:'撤销 Word 恢复',icon:'undo',fn:()=>SC.undoDittoWordRestore()}]:[]),...['word','grammar','sentence'].map(kind=>({label:'新建'+SC.cardLabel(kind),icon:SC.cardIcon(kind),fn:()=>createBook(kind,projectId)})),{separator:true},...['expressions','forms','sentence'].map(module=>({label:(project.modules.includes(module)?'移除 ':'添加 ')+routeNames[module],icon:'wave',fn:()=>{project.modules=project.modules.includes(module)?project.modules.filter(entry=>entry!==module):[...project.modules,module];project.expanded=true;SC.persist();SC.render();}})),{separator:true},...SC.data.groups.filter(group=>group.id!==project.groupId).map(group=>({label:'移到 '+group.name,icon:'folder',fn:()=>moveNotebook(projectId,group.id)})),...(project.groupId?[{label:'移到其他',icon:'notebook',fn:()=>moveNotebook(projectId,null)}]:[]),{label:'重命名',icon:'pencil',fn:()=>SC.editFields('重命名',[{key:'name',label:'笔记本名称',value:project.name,required:true}],values=>{project.name=values.name.trim();SC.persist();SC.render();})},{label:'删除…',icon:'deleteAll',fn:()=>SC.beginContainerDelete('project',projectId)}]);}
function clearConversation(){
  SC.ui.chatEpoch=(SC.ui.chatEpoch||0)+1;SC.ui.chatBusy=false;SC.ui.answerOpen=false;
  const urls=new Set([...SC.attachments,...SC.chat.flatMap(message=>message.files||[])].map(file=>file.url).filter(Boolean));urls.forEach(url=>URL.revokeObjectURL(url));
  SC.chat=[];SC.candidates=[];SC.selected.clear();SC.attachments=[];SC.ui.chatDrafts=new Map();SC.ui.organizeDraft=null;SC.ui.draft='';
  if(SC.$('#dialogBody [data-chat-organizer]')){SC.$('#dialog').close();SC.$('#dialogBody').replaceChildren();SC.$('#dialogActions').replaceChildren();}renderComposer();renderAnswers();if(SC.route==='home')home();
}
SC.go=(route,entityId)=>{
  SC.ui.navigationEpoch=(SC.ui.navigationEpoch||0)+1;
  SC.clearManagement?.();SC.stopSpeech();closeMenu(false);SC.$('#hoverPreview').hidden=true;
  const project=SC.data.projects.find(row=>row.id===entityId),group=SC.data.groups.find(row=>row.id===entityId);
  if(entityId&&entityId!=='other'&&(SC.data.deletedContainers?.[entityId]||!(isBookRoute(route)?SC.data.books.some(book=>book.id===entityId):project||group))){SC.toast('内容已删除或不存在。');return false;}
  if(route==='scope'&&entityId){
    if(project?.id.startsWith('song:')){if(!SC.restoreSavedSong?.(project.id))return false;route='songs';}
    else route='scope';
  }
  SC.combinedBook=null;SC.route=route;
  if(isBookRoute(route)){SC.bookId=entityId||SC.bookId;const book=SC.data.books.find(row=>row.id===SC.bookId);SC.projectId=book?.projectId||null;SC.groupId=book?.groupId||null;}
  else if(route==='songs'){const songProject=project?.id.startsWith('song:')?project:SC.song.id?SC.ensureSongBooks().project:null;if(!songProject){SC.projectId=null;SC.groupId=null;}else if(songProject.deleted){SC.toast('这首歌曲的保存内容已删除或不存在。');SC.route='scope';SC.projectId=null;SC.groupId=null;}else{SC.projectId=songProject.id;SC.groupId=songProject.groupId||null;}}
  else if(entityId){SC.projectId=project?.id||null;SC.groupId=group?.id||null;}
  const currentBook=isBookRoute(route)&&SC.data.books.find(book=>book.id===SC.bookId),currentProject=SC.data.projects.find(project=>project.id===SC.projectId),currentGroup=SC.data.groups.find(group=>group.id===(currentProject?.groupId||SC.groupId));
  if(currentBook&&!currentBook.special)currentBook.lastUsed=Date.now();
  if(isBookRoute(route)||route==='songs'||entityId&&entityId!=='other'){if(currentProject)touchSidebarContainer(currentProject,'project');if(currentGroup)touchSidebarContainer(currentGroup,'group');}
  SC.data.lastProject=SC.projectId;SC.data.lastGroup=SC.groupId;SC.persist();SC.render(true);SC.root.scrollTop=0;if(route==='songs'&&SC.player.available&&SC.ui.savedSongNavigation!==SC.song.id)SC.playSong();return true;
};
function scopeContent(){
  const project=SC.data.projects.find(row=>row.id===SC.projectId),group=SC.data.groups.find(row=>row.id===SC.groupId),missing=SC.projectId&&!project||SC.groupId&&!group;
  if(missing){SC.root.innerHTML='<div class="empty-state">内容已删除或不存在。</div>';return;}
  const notebooks=project?[]:allContainers(notebooksInScope(group?.id||''),'project',group?.id||'');
  const books=orderedBooks(SC.data.books.filter(book=>project?book.projectId===project.id:!book.projectId&&(group?book.groupId===group.id:!book.groupId)));
  const modules=project?orderedModules(project):[];
  const section=(title,rows)=>rows.length?`<section class="scope-content-section"><h2>${title}</h2><div class="collection-results">${rows.join('')}</div></section>`:'';
  const entry=(route,id,label,icon)=>`<button type="button" class="collection-entry" data-scope-route="${route}" data-scope-id="${SC.esc(id)}">${SC.icon(icon)}<span>${SC.esc(label)}</span></button>`;
  SC.root.innerHTML=`<div class="scope-content">${section('笔记本',notebooks.map(row=>entry('scope',row.id,row.name,'notebook')))}${section('卡片',books.map(book=>entry(cardRoute(book.kind),book.id,book.name,SC.cardIcon(book.kind))))}${section('练习',modules.map(module=>entry(module,project.id,routeNames[module],'wave')))}${!notebooks.length&&!books.length&&!modules.length?'<div class="empty-state">这里还没有内容。</div>':''}</div>`;
  SC.root.querySelectorAll('[data-scope-route]').forEach(button=>button.onclick=()=>SC.go(button.dataset.scopeRoute,button.dataset.scopeId));
}
function breadcrumb(){
  const project=SC.data.projects.find(row=>row.id===SC.projectId),group=SC.data.groups.find(row=>row.id===(project?.groupId||SC.groupId)),book=SC.data.books.find(row=>row.id===SC.bookId),parents=[];
  let title=routeNames[SC.route]||'内容已删除';
  if(book?.special)title=book.name;
  else if(!['home','combined'].includes(SC.route)&&!(SC.route==='songs'&&!SC.song.id)){
    if(group)parents.push({id:group.id,label:group.name});else parents.push({id:'other',label:'其他'});
    if(project)parents.push({id:project.id,label:project.name});
    if(SC.route==='scope')title=parents.pop()?.label||'其他';
    else if(SC.route==='songs')title=parents.pop()?.label||SC.song.title;
    else if(isBookRoute(SC.route))title=book?.name||'内容已删除';
  }
  const returnable=isBookRoute(SC.route)||SC.route==='combined';
  SC.$('#breadcrumb').innerHTML=parents.map(parent=>`<span class="crumb"><button type="button" class="crumb-link" data-crumb-id="${SC.esc(parent.id)}">${SC.esc(parent.label)}</button></span>`).concat(`<h1 class="crumb page-title" aria-current="page">${returnable?`<button type="button" id="pageReturn" title="${SC.route==='combined'?'返回范围选择':book?.kind==='sentence'?'返回阅读':'返回卡片'}">${SC.esc(title)}</button>`:SC.esc(title)}</h1>`).join(SC.icon('right'));
  SC.$('#breadcrumb').querySelectorAll('[data-crumb-id]').forEach(button=>button.onclick=()=>SC.go('scope',button.dataset.crumbId));
  const pageReturn=SC.$('#pageReturn');if(pageReturn)pageReturn.onclick=()=>{SC.clearManagement?.();if(SC.route==='combined'){if(SC.ui.combined)SC.ui.combined.active=false;SC.endCombinedBookRound();}else SC.returnToBookList(SC.bookId);};
}
SC.render=(announce=false)=>{sidebar();breadcrumb();document.body.classList.toggle('home-empty',SC.route==='home'&&!SC.chat.length);if(SC.route==='home')home();else if(SC.route==='scope')scopeContent();else if(isBookRoute(SC.route))SC.renderBook(SC.bookId,announce);else if(SC.route==='songs'){if(SC.song.id&&(SC.data.deletedContainers?.['song:'+SC.song.id]||!SC.data.projects.some(row=>row.id==='song:'+SC.song.id)))SC.root.innerHTML='<div class="empty-state">这首歌曲的保存内容已删除或不存在。</div>';else{SC.songRender(SC.root);sidebar();}}else if(SC.route==='combined'){if(SC.combinedBook)SC.renderBook(SC.combinedBook.id,announce);else (SC.combinedRender||SC.renderCombined)?.(SC.root,announce);}else SC.practiceRender(SC.root,announce);renderAnswers();};
function targetButton(kind,label,target){const book=SC.data.books.find(b=>b.id===target);return `<button type="button" class="notebook-selector" data-target-kind="${kind}" aria-label="目标${label}" aria-haspopup="menu" aria-expanded="false" aria-controls="contextMenu">${SC.icon(SC.cardIcon(kind))}<span>${SC.esc(book?.name||'选择本子')}</span>${SC.icon('down')}</button>`;}
function chatFilesHTML(files){return (files||[]).map(file=>`<details class="chat-source"><summary>${SC.esc(file.file.name)}</summary>${file.uploaded?`<a href="/api/files/${SC.esc(file.uploaded.file_id)}" target="_blank" rel="noopener">原文件</a>`:''}${(file.units||[]).map(unit=>`<small>${SC.esc(unit.location)}</small><p>${SC.esc(unit.text)}</p>`).join('')}${(file.notices||[]).map(text=>`<p class="chat-status">${SC.esc(text)}</p>`).join('')}</details>`).join('');}
function bubbleHTML(message,panel=false){const ready=message.status==='ready',interactive=ready?`tabindex="0" role="button" aria-description="双击或 Enter 整理卡片"`:'';return `<div class="chat-bubble ${message.role} ${panel?'answer-message':''}" data-chat-id="${message.id}" ${interactive}>${ready&&message.role==='assistant'?`<small class="chat-status">${message.origin==='source'?'原文摘录':'AI 回答'}</small>`:''}<div class="chat-bubble-content">${SC.esc(message.text)}</div>${chatFilesHTML(message.files)}${(message.notices||[]).map(text=>`<small class="chat-status">${SC.esc(text)}</small>`).join('')}${message.status==='pending'?'<small class="chat-status" role="status">正在回答…</small>':''}${message.status==='error'?`<button type="button" class="plain-button" data-retry-chat="${message.roundId}">重试</button>`:''}</div>`;}
function wireBubbles(container){container.querySelectorAll('[data-chat-id]').forEach(element=>{const open=()=>{const message=SC.chat.find(row=>row.id===element.dataset.chatId);if(message?.status==='ready')openChatOrganizer(message);};element.ondblclick=event=>{if(!event.target.closest('button,a,details'))open();};element.onkeydown=event=>{if(event.target===element&&event.key==='Enter'&&!event.repeat&&!event.isComposing&&!event.ctrlKey&&!event.altKey&&!event.metaKey){event.preventDefault();event.stopPropagation();open();}};});container.querySelectorAll('[data-retry-chat]').forEach(button=>button.onclick=()=>{const user=SC.chat.find(row=>row.roundId===button.dataset.retryChat&&row.role==='user'),answer=SC.chat.find(row=>row.roundId===button.dataset.retryChat&&row.role==='assistant');if(user&&answer&&!SC.ui.chatBusy)replyMessage(user,answer,SC.ui.chatEpoch||0);});}
function home(){const scroll=SC.root.scrollTop,follow=SC.root.scrollHeight-SC.root.clientHeight-scroll<60,last=SC.data.items.find(note=>note.id===(SC.data.lastStudiedWord?.id||SC.data.lastStudied?.id)&&note.kind==='word');document.body.classList.toggle('home-empty',!SC.chat.length);SC.root.innerHTML=`<div class="chat-home"><div class="chat-bubbles" aria-live="polite">${SC.chat.map(message=>bubbleHTML(message)).join('')||`<div class="chat-empty">${last?`<button type="button" id="recentStudy" class="recent-knowledge"><span class="recent-label">知识温故：</span><strong class="ko">${SC.esc(last.text)}</strong><span>${SC.esc(SC.studyMeaning(last))}</span></button>`:''}</div>`}</div></div>`;wireBubbles(SC.root);if(SC.$('#recentStudy'))SC.$('#recentStudy').onclick=()=>SC.go('words',last.bookId);SC.root.scrollTop=follow?SC.root.scrollHeight:scroll;}
function refreshChat(){if(SC.route==='home')home();renderAnswers();renderComposer();}
async function chatRequest(path,body){const response=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'本机服务请求失败，请重试。');return result;}
function requireTextAPI(cfg){if(!cfg.api_key_set||cfg.demo)throw new Error('请先在 API 中配置文本模型并测试连接。');}
async function uploadChatFiles(user,cfg,epoch){for(const file of user.files){if(epoch!==(SC.ui.chatEpoch||0))return;if(!file.uploaded){const projectId=await SC.ensureBackendProject(user.container,'input');if(epoch!==(SC.ui.chatEpoch||0))return;const data=new FormData();data.append('project_id',projectId);data.append('file',file.file);const response=await fetch('/api/upload',{method:'POST',body:data}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'文件提取失败，附件仍保留。');file.uploaded=result;file.units=result.units||[];file.notices=result.warning?[result.warning]:[];}
    for(const unit of file.units){if(!unit.image_id||unit.text?.trim()||unit.imageHandled)continue;file.notices=file.notices.filter(text=>!text.startsWith(unit.location+'：'));if(!cfg.api_key_set||cfg.demo||!cfg.vision_model){file.notices.push(`${unit.location}：未配置视觉模型，图片尚未识别。`);continue;}try{const result=await chatRequest('/api/image/'+encodeURIComponent(unit.image_id),{});if(epoch!==(SC.ui.chatEpoch||0))return;unit.text=(result.items||[]).map(row=>row.context||row.text).filter(Boolean).join('\n');unit.imageHandled=true;file.notices.push(`${unit.location}：已取得识别片段，并非完整文字识别。`);}catch(error){file.notices.push(`${unit.location}：${error.message}`);}}
    SC.attachments=SC.attachments.filter(row=>row!==file);
  }}
function materialFor(user){
  const sources=[...(user.context?.source_units||[])],attachments=[];
  for(const file of user.files||[]){const batches=SC.sourceNoteBatches?SC.sourceNoteBatches(file.units||[]):(file.units||[]).map(unit=>[unit]);if(batches.skipped?.length)user.partial=true;for(const [index,batch] of batches.entries()){const text=batch.map(unit=>unit.text).join('\n');if(!text.trim())continue;const sourceId='upload:'+file.uploaded?.file_id+':'+index;if(text.length>6000){user.partial=true;continue;}sources.push({id:sourceId,source_kind:'note',text,original_note:text,source_file_id:file.uploaded?.file_id||'',source_locations:batch.map(unit=>unit.location||'')});attachments.push({file:file.file.name,location:batch.map(unit=>unit.location||'').join('、'),source_id:sourceId});}}
  const material={selected:user.context.text,attachments,source_units:sources,notices:(user.files||[]).flatMap(file=>file.notices||[])};
  while(JSON.stringify(material).length>23000&&material.source_units.length){const removed=material.source_units.pop();material.attachments=material.attachments.filter(unit=>unit.source_id!==removed.id);user.partial=true;}
  if(user.partial)material.partial='本轮只使用部分完整原文，其他提取文字仍可查看。';return material;
}
async function replyMessage(user,answer,epoch){
  SC.ui.chatBusy=true;answer.status='pending';answer.text='';refreshChat();
  try{
    const cfg=await chatRequest('/api/settings');await uploadChatFiles(user,cfg,epoch);if(epoch!==(SC.ui.chatEpoch||0))return;
    user.status='ready';const material=materialFor(user);if(user.partial)user.notices=['本轮回答只使用部分完整原文，其他提取内容保留。'];
    const earlier=SC.chat.slice(0,SC.chat.indexOf(user)).filter(row=>row.status==='ready').map(row=>({role:row.role,text:row.text}));let history=earlier.slice(-8);while(history.reduce((sum,row)=>sum+row.text.length,0)>14000)history.shift();
    const result=await chatRequest('/api/chat',{transient:true,text:user.text,material,history});if(epoch!==(SC.ui.chatEpoch||0))return;
    answer.text=result.answer_zh;answer.source_units=result.source_units||[];answer.origin=result.origin||'ai';answer.status='ready';
  }catch(error){if(epoch!==(SC.ui.chatEpoch||0))return;user.status='ready';answer.status='error';answer.text=error.message;}
  finally{if(epoch===(SC.ui.chatEpoch||0)){SC.ui.chatBusy=false;refreshChat();}}
}
