      const origins=draft.sourceUnits.filter(unit=>batch.some(part=>unit.text.includes(part.text))),origin=origins.length&&origins.every(unit=>unit.source_file_id===origins[0].source_file_id)?{source_file_id:origins[0].source_file_id,source_locations:origins.flatMap(unit=>unit.source_locations||[])}:null;
