  return `<section><div class="section-title"><h2>${label}</h2>${targetButton(kind,label,SC[targetFor(kind)])}</div>${SC.batchToolbar({action:batch?.action,label:batch?.action==='save'?'保存所选':'删除所选',count:selected.length,all:!!group.length&&selected.length===group.length,prefix:'candidate-'+kind})}<div class="chat-candidate-grid">${group.map(note=>`<div class="candidate ${kind==='grammar'?'candidate-grammar':''} ${draft.selected.has(note.cid)?'selected':''}">${batch?`<input type="checkbox" data-pick="${note.cid}" ${draft.selected.has(note.cid)?'checked':''} aria-label="选择 ${SC.esc(note.text)}">`:''}<div class="candidate-text ${kind==='word'?'candidate-word':kind==='sentence'?'candidate-sentence':''}" data-candidate="${note.cid}" tabindex="0" aria-label="${SC.esc(note.text)}"><strong>${SC.esc(note.text)}</strong>${kind==='grammar'?`<p>${SC.esc(note.explanation)}</p>`:`<span>${SC.esc(note.meaning||note.meaningZh)}</span>${kind==='word'?SC.wordFormHTML(note):''}`}</div>${note.saved?'<span class="saved-dot">已保存</span>':''}</div>`).join('')}</div></section>`;
